const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
function artwork(value,large=false) {
 if(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+=*$/.test(value||'')||/^\/api\/images\/[a-f0-9-]{36}$/.test(value||''))return `<img class="product-photo ${large?'large':''}" src="${e(value)}" alt="Фото товара" loading="lazy" decoding="async">`;
 return `<span class="photo-placeholder" aria-label="Нет фотографии">${icon('box')}</span>`;
}
async function readPhoto(file,compact=false) {
 if(!file)return '';
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Выберите фото JPG, PNG или WebP.');
 if(file.size>10*1024*1024)throw new Error('Исходное фото должно быть не больше 10 МБ.');
 const bitmap=await createImageBitmap(file);
 try {
  let scale=Math.min(1,(compact?1000:1200)/Math.max(bitmap.width,bitmap.height));
  const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
  const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);
  let result=canvas.toDataURL('image/jpeg',compact?0.78:0.82);
  if(compact){let quality=0.78;while(result.length>200000){if(quality>0.5)quality-=0.1;else {scale*=0.8;canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);}result=canvas.toDataURL('image/jpeg',quality);}}
  if(result.length>700000)throw new Error('Фото слишком большое после обработки. Выберите другое изображение.');
  return result;
 } finally {bitmap.close();}
}
const nav=[['statistics','chart','Статистика'],['products','box','Товары'],['customers','users','Клиенты'],['orders','bag','Заказы'],['finance','wallet','Операции'],['reviews','star','Отзывы'],['referrals','gift','Реферальная программа'],['content','settings','Редактирование']];
const statusLabels={new:'Новый',accepted:'В работе',completed:'Выполнен',cancelled:'Отменён',pending:'На модерации',published:'Опубликован',hidden:'Скрыт'};
let state={user:null,data:null,page:'products',query:'',filter:'all',category:'all',pageNumber:1,selected:new Set(),customerSelected:new Set(),customerMinSpent:0,customerMinOrders:0,productSort:'manual',contentTab:'info'};
let previousFocus=null;
