function moveCategory(from,to){const form=$('#category-order-form');if(!form||form.getAttribute('aria-busy')==='true')return;const names=form._categories;if(to<0||to>=names.length||from===to)return;names.splice(to,0,...names.splice(from,1));renderCategoryOrder();}
let draggedCategory=null;
document.addEventListener('dragstart',event=>{const row=event.target.closest('#category-order-list [data-category-index]');if(!row)return;draggedCategory=Number(row.dataset.categoryIndex);event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(draggedCategory));});
document.addEventListener('dragover',event=>{if(draggedCategory!==null&&event.target.closest('#category-order-list [data-category-index]'))event.preventDefault();});
document.addEventListener('drop',event=>{const row=event.target.closest('#category-order-list [data-category-index]');if(row&&draggedCategory!==null){event.preventDefault();moveCategory(draggedCategory,Number(row.dataset.categoryIndex));}draggedCategory=null;});
document.addEventListener('dragend',()=>{draggedCategory=null;});
