document.addEventListener('change',async event=>{
 const el=event.target;
 if(el.id==='statistics-month'){if(/^\d{4}-\d{2}$/.test(el.value)&&Number(el.value.slice(0,4))>0){state.statisticsMonth=el.value;renderMain();}return;}
 if(el.dataset.descriptionColor){const input=document.getElementById(el.dataset.descriptionColor);if(input.selectionStart===input.selectionEnd){toast('Сначала выделите текст описания');return;}const text=input.value.slice(input.selectionStart,input.selectionEnd);const replacement=`[color=${el.value}]${text}[/color]`;if(input.value.length-text.length+replacement.length>2000){toast('Описание слишком длинное',true);return;}input.setRangeText(replacement,input.selectionStart,input.selectionEnd,'select');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();}
 if(el.id==='product-photo-file'){
  const files=[...el.files];if(!files.length)return;
  const form=el.closest('form'),submit=form.querySelector('[type=submit]'),error=form.querySelector('#photo-error'),progress=form.querySelector('#photo-progress');
  if(form._photos.length+files.length>10){error.textContent='Можно добавить до 10 фотографий.';el.value='';return;}
  submit.disabled=true;el.disabled=true;form.dataset.photosLoading='true';error.textContent='';renderProductPhotos(form);
  try {for(const [index,file] of files.entries()){
    if(!form.isConnected)break;
    progress.textContent=`Загрузка фото ${index+1} из ${files.length}…`;
    const image=await readPhoto(file,true);if(!form.isConnected)break;
    const saved=await api('/images',{method:'POST',body:{image}});
    form._photos.push(saved.image);renderProductPhotos(form);
  }progress.textContent='Фотографии загружены';}
  catch(err){error.textContent=err.message;progress.textContent='';}
  finally {delete form.dataset.photosLoading;submit.disabled=false;el.disabled=false;el.value='';renderProductPhotos(form);}
 }
 if(el.id==='banner-photo-file'){
  if(!el.files.length)return;
  const form=el.closest('form'),submit=form.querySelector('[type=submit]'),error=form.querySelector('#photo-error');
  submit.disabled=true;error.textContent='';
  try {const image=await readPhoto(el.files[0]);form.querySelector('[name=image]').value=image;form.querySelector('#banner-photo-preview').innerHTML=`<img src="${e(image)}" alt="Изображение баннера">`;}
  catch(err){error.textContent=err.message;el.value='';}
  finally {submit.disabled=false;}
 }
 if(el.dataset.productOrder){el.disabled=true;try{const n=Number(el.value);if(!Number.isSafeInteger(n)||n<0||n>1000000)throw new Error('Сортировка: целое число от 0 до 1000000.');await mutate(`/products/${el.dataset.productOrder}`,{sort_order:n});}catch(err){toast(err.message,true);renderMain();}finally{el.disabled=false;}}
 if(el.id==='product-status-filter'||el.id==='customer-status-filter'){if(el.id==='product-status-filter')state.selected.clear();state.filter=el.value;state.pageNumber=1;renderMain();}
 if(el.dataset.customerSelect){el.checked?state.customerSelected.add(Number(el.dataset.customerSelect)):state.customerSelected.delete(Number(el.dataset.customerSelect));renderMain();}
 if(el.id==='select-all-customers'){$$('[data-customer-select]').forEach(input=>el.checked?state.customerSelected.add(Number(input.dataset.customerSelect)):state.customerSelected.delete(Number(input.dataset.customerSelect)));renderMain();}
 if(el.id==='category-filter'){state.category=el.value;state.pageNumber=1;renderMain();}
 if(el.dataset.select){el.checked?state.selected.add(Number(el.dataset.select)):state.selected.delete(Number(el.dataset.select));renderMain();}
 if(el.id==='select-all'){$$('[data-select]').forEach(input=>el.checked?state.selected.add(Number(input.dataset.select)):state.selected.delete(Number(input.dataset.select)));renderMain();}
});
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target;const fd=new FormData(form);const b=Object.fromEntries(fd);const submit=$('[type=submit]',form);if(!submit||submit.disabled)return;submit.disabled=true;const submitHTML=submit.innerHTML;submit.textContent='Сохранение…';form.setAttribute('aria-busy','true');const errorNode=$('.form-error',form);if(errorNode)errorNode.textContent='';
 try {
  if(form.id==='login-form'){state.user=await api('/auth/login',{method:'POST',body:b});await refresh();}
  else if(form.id==='operation-delete-form'){const routes={purchase:'purchases',sale:'sales',order:'orders',transaction:'transactions'};await api(`/${routes[form.dataset.kind]}/${form.dataset.id}`,{method:'DELETE'});await refresh();closeModal();toast('Операция удалена');}
  else if(form.id==='product-form'){for(const key of ['price','cost','stock','sort_order'])if(key in b)b[key]=Number(b[key]);b.images=JSON.parse(b.images);b.active=fd.has('active');const id=form.dataset.id;if(id)b.visible=fd.has('visible');await mutate(id?`/products/${id}`:'/products',b,id?'PATCH':'POST',id?'Товар обновлён':'Товар добавлен');closeModal();}
  else if(form.id==='delete-category-form'){await api('/categories',{method:'DELETE',body:b});state.category='all';state.selected.clear();await refresh();closeModal();toast('Категория удалена');}
  else if(form.id==='category-order-form'){await mutate('/categories/order',{names:form._categories},'PATCH','Порядок категорий сохранён');closeModal();}
  else if(form.id==='category-form'){await mutate('/categories',b,'POST','Категория добавлена');closeModal();}
  else if(form.id==='customer-form'){const id=form.dataset.id;await mutate(id?`/customers/${id}`:'/customers',b,id?'PATCH':'POST',id?'Клиент обновлён':'Клиент добавлен');closeModal();}
  else if(form.id==='customer-filters-form'){state.customerMinSpent=Number(b.minSpent);state.customerMinOrders=Number(b.minOrders);state.pageNumber=1;closeModal();renderMain();}
  else if(form.id==='delete-records-form'){for(const id of form.dataset.ids.split(','))await api(`/${form.dataset.kind}/${id}`,{method:'DELETE'});state.selected.clear();state.customerSelected.clear();await refresh();closeModal();toast('Удалено');}
  else if(form.id==='banner-form'){b.active=fd.has('active');const id=form.dataset.id;await mutate(id?`/banners/${id}`:'/banners',b,id?'PATCH':'POST');closeModal();}
  else if(form.id==='order-form'){await mutate(`/orders/${form.dataset.id}`,b);closeModal();}
  else if(form.id==='purchase-form'){if(!purchaseDraft.items.length)throw new Error('Добавьте товары в документ.');const kind=purchaseKind,route=kind==='sale'?'sales':'purchases',payload={...purchaseDraft,...b,posted:fd.has('posted'),paid:Number(b.paid),items:purchaseDraft.items.map(item=>kind==='sale'?{product_id:item.product_id,quantity:item.quantity,price:item.cost}:item)};const saved=await api(purchaseDraft.id?`/${route}/${purchaseDraft.id}`:`/${route}`,{method:purchaseDraft.id?'PATCH':'POST',body:payload});await refresh();purchaseModal(saved.id,kind);toast(payload.posted?'Документ проведён':'Черновик сохранён');}
  else if(form.id==='transaction-form'){b.amount=Number(b.amount);await mutate(form.dataset.id?`/transactions/${form.dataset.id}`:'/transactions',b,form.dataset.id?'PATCH':'POST','Операция сохранена');closeModal();}
  else if(form.id==='shop-form')await mutate('/settings/shop',b);
  else if(form.id==='referral-form'){b.enabled=fd.has('enabled');b.bonus=Number(b.bonus);b.minPayout=Number(b.minPayout);await mutate('/settings/referral',b);}
 }catch(error){if(errorNode&&errorNode.isConnected)errorNode.textContent=error.message;else toast(error.message,true);}
 finally{submit.disabled=false;submit.innerHTML=submitHTML;form.removeAttribute('aria-busy');}
});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);state.page=nav.some(n=>n[0]===page)?page:'products';state.query='';state.filter=requestedFilter||'all';requestedFilter=null;state.category='all';state.pageNumber=1;state.selected.clear();document.body.classList.remove('nav-open');closeModal();if(state.user&&state.data)renderShell();});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){closeModal();document.body.classList.remove('nav-open');}
 const modal=$('.modal');
 if(modal&&event.key==='Tab'){const nodes=$$('button:not([disabled]),a[href],input:not([disabled]),select,textarea,[tabindex="0"]',modal).filter(n=>n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first?.focus();}}
 if(event.key==='/'&&!modal&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();$('#table-search')?.focus();}
});
async function init(){
 state.page=location.hash.slice(1)||'products';if(!nav.some(n=>n[0]===state.page))state.page='products';
 try{state.data=await api('/bootstrap');state.user=state.data.user;renderShell();}
 catch(error){if(error.status===401)renderLogin();else $('#app').innerHTML=`<div class="initial-loading"><h2>Не удалось загрузить магазин</h2><p>${e(error.message)}</p><button class="button primary" data-action="reload">Повторить</button></div>`;}
}
